    hk_title: "Hotkeys", hk_hint: "Control LiveLingo from inside a game without switching back. LiveLingo is only told about the combinations you set here; it does not read any other key.", hk_overlay: "Show or hide subtitles", hk_overlay_desc: "Hides the floating chat or subtitle bar on screen; press again to bring it back.", hk_mic: "Turn the microphone on or off", hk_mic_desc: "Starts or stops listening to you. A short note on screen tells you which.", hk_copy: "Copy my last translation", hk_copy_desc: "Copies the translation of the last thing you said or typed again, so you can paste it into your chat app yourself.", hk_quick: "Quick input box", hk_quick_desc: "Opens a small box over the game. Type, press Enter, and the translation is copied; the box closes itself. LiveLingo never types or pastes into another program for you.", hk_press: "Press the new keys…", hk_rec_hint: "Esc to cancel, Backspace for no hotkey", hk_none: "Not set", hk_change: "Change the hotkey for {name}, currently {combo}", hk_clear: "Remove the hotkey for {name}", hk_ok: "Working", hk_taken: "Another program already uses these keys. Pick a different combination.", hk_need_mod: "Add Ctrl, Alt, Shift or Win, so it does not take over a key you type or play with", hk_bad_key: "Only letters, digits and F1 to F12 can be used", hk_unavailable: "Global hotkeys only work in the Windows app. Your choices are still saved.", hk_try: "Open the quick input box now", hk_reset: "Restore default hotkeys", n_hotkey_invalid: "That combination cannot be used as a hotkey.", n_hotkey_same: "Another action already uses these keys. Pick a different combination.", n_hotkey_note: "{text}",
